function safeStringify(value) {
    if (value === null) return 'null';
    if (value === undefined) return 'undefined';
    try {
        // 首先尝试标准字符串转换
        return String(value);
    } catch (e) {
        try {
            // 如果失败，尝试 JSON 序列化
            return JSON.stringify(value);
        } catch (e2) {
            // 如果 JSON 序列化也失败（如循环引用），返回类型信息
            return '[object ' + Object.prototype.toString.call(value).slice(8, -1) + ']';
        }
    }
}

class ObjectPool {
    constructor(factory, resetFn, size = 100) {
        this._factory = factory;
        this._resetFn = resetFn;
        this._pool = [];
        this._size = size;
        this._created = 0;

        // 预创建对象
        for (let i = 0; i < size / 2; i++) {
            this._pool.push(this._factory());
            this._created++;
        }
    }

    acquire() {
        if (this._pool.length > 0) {
            return this._pool.pop();
        }
        this._created++;
        return this._factory();
    }

    release(obj) {
        if (this._pool.length < this._size) {
            this._resetFn(obj);
            this._pool.push(obj);
        }
    }

    getStats() {
        return {
            available: this._pool.length,
            created: this._created,
            utilization: ((this._created - this._pool.length) / this._created * 100).toFixed(1) + '%'
        };
    }
}

class ErrorHandler {
    constructor() {
        this._errorCounts = {};
        this._errorLog = [];
        this._maxLogSize = 1000;
    }

    handle(error, context = {}) {
        const category = this._categorize(error);
        this._errorCounts[category] = (this._errorCounts[category] || 0) + 1;

        const entry = {
            timestamp: new Date().toISOString(),
            category,
            message: error.message,
            stack: error.stack,
            context
        };

        this._errorLog.push(entry);
        if (this._errorLog.length > this._maxLogSize) {
            this._errorLog.shift();
        }

        // 根据错误类型采取不同策略
        switch (category) {
            case 'TRANSIENT':
                return this._retry(error, context);
            case 'FATAL':
                return this._gracefulDegradation(error, context);
            default:
                return this._logAndContinue(error, context);
        }
    }

    _categorize(error) {
        if (error.message.includes('network') || error.message.includes('timeout')) {
            return 'TRANSIENT';
        }
        if (error.message.includes('memory') || error.message.includes('fatal')) {
            return 'FATAL';
        }
        return 'RECOVERABLE';
    }

    getStats() {
        return {
            counts: this._errorCounts,
            total: Object.values(this._errorCounts).reduce((a, b) => a + b, 0),
            recent: this._errorLog.slice(-10)
        };
    }
}
